CREATE SCHEMA marts;;
CREATE SCHEMA seeds;;
CREATE SCHEMA semantic;;
CREATE SCHEMA staging;;
CREATE TABLE marts.awards(player_id INTEGER, season VARCHAR, season_start INTEGER, award VARCHAR, award_type VARCHAR, team_name VARCHAR, team_number VARCHAR, conference VARCHAR, "month" VARCHAR, "week" VARCHAR);;
CREATE TABLE marts.franchises(franchise_id INTEGER, current_name VARCHAR, start_year INTEGER, end_year INTEGER, defunct BOOLEAN);;
