CREATE TABLE marts.player_season(player_id INTEGER, season VARCHAR, season_start INTEGER, season_type VARCHAR, team_count BIGINT, last_team_id INTEGER, player_age INTEGER, gp INTEGER, gs INTEGER, "minutes" DOUBLE, fgm INTEGER, fga INTEGER, fg3m INTEGER, fg3a INTEGER, ftm INTEGER, fta INTEGER, oreb INTEGER, dreb INTEGER, reb INTEGER, ast INTEGER, stl INTEGER, blk INTEGER, tov INTEGER, pf INTEGER, pts INTEGER);;
