CREATE TABLE marts.records(record VARCHAR, record_kind VARCHAR, stat VARCHAR, player_id INTEGER, game_id VARCHAR, game_date DATE, season VARCHAR, season_type VARCHAR, "value" DOUBLE, valid_from DATE, "source" VARCHAR);;
CREATE TABLE marts.shots(game_id VARCHAR, game_event_id INTEGER, season_type VARCHAR, game_date DATE, player_id INTEGER, team_id INTEGER, period INTEGER, minutes_remaining INTEGER, seconds_remaining INTEGER, action_type VARCHAR, shot_type VARCHAR, "zone" VARCHAR, zone_area VARCHAR, zone_range VARCHAR, distance_ft INTEGER, x INTEGER, y INTEGER, made BOOLEAN, season VARCHAR);;
CREATE TABLE marts.stat_availability(stat VARCHAR, first_season VARCHAR, first_season_start INTEGER, note VARCHAR);;
CREATE TABLE marts.teams(team_id INTEGER, franchise_id INTEGER, city VARCHAR, "name" VARCHAR, full_name VARCHAR, first_season_start INTEGER, last_season_start INTEGER, valid_from DATE, valid_to DATE, is_current BOOLEAN);;
CREATE TABLE marts.team_aliases(team_id INTEGER, alias VARCHAR, alias_norm VARCHAR, kind VARCHAR);;
CREATE TABLE marts.team_season(team_id INTEGER, franchise_id INTEGER, season VARCHAR, season_start INTEGER, season_type VARCHAR, gp BIGINT, wins BIGINT, losses BIGINT, win_pct DOUBLE, home_wins BIGINT, home_losses BIGINT, road_wins BIGINT, road_losses BIGINT, neutral_games BIGINT, pts HUGEINT, opp_pts HUGEINT, fgm HUGEINT, fga HUGEINT, fg3m HUGEINT, fg3a HUGEINT, ftm HUGEINT, fta HUGEINT, reb HUGEINT, ast HUGEINT, tov HUGEINT, conference VARCHAR, division VARCHAR, conference_rank INTEGER, league_rank INTEGER, off_rating DOUBLE, def_rating DOUBLE, net_rating DOUBLE, pace DOUBLE);;
CREATE TABLE marts.team_titles(franchise_id INTEGER, team_id INTEGER, season VARCHAR, season_start INTEGER, champion_name VARCHAR, opponent_team_id INTEGER, opponent_name VARCHAR);;
CREATE TABLE seeds.award_timing(award VARCHAR, known_at VARCHAR);;
CREATE TABLE seeds.known_boxscore_gaps(game_id VARCHAR, team_id INTEGER, season VARCHAR, team_pts INTEGER, player_pts INTEGER, note VARCHAR);;
CREATE TABLE seeds.known_stint_total_gaps(player_id INTEGER, season VARCHAR, season_type VARCHAR, difference VARCHAR, note VARCHAR);;
CREATE TABLE seeds.known_team_record_gaps(team_id INTEGER, season VARCHAR, games_missing INTEGER, note VARCHAR);;
