CREATE VIEW semantic.awards AS SELECT a.*, p."name" AS player_name FROM nba_fixture.marts.awards AS a INNER JOIN nba_fixture.marts.players AS p USING (player_id);;
CREATE VIEW semantic.franchises AS SELECT * FROM nba_fixture.marts.franchises;;
CREATE VIEW semantic.games AS SELECT g.*, h.full_name AS home_team_name, a.full_name AS away_team_name FROM nba_fixture.marts.games AS g LEFT JOIN nba_fixture.marts.teams AS h ON (((h.team_id = g.home_team_id) AND (g.season_start BETWEEN h.first_season_start AND h.last_season_start))) LEFT JOIN nba_fixture.marts.teams AS a ON (((a.team_id = g.away_team_id) AND (g.season_start BETWEEN a.first_season_start AND a.last_season_start)));;
CREATE VIEW semantic.league_season_stats AS WITH spine AS (SELECT season, any_value(season_start) AS season_start, season_type, count(DISTINCT team_id) AS teams FROM nba_fixture.marts.team_season GROUP BY season, season_type), m0 AS (SELECT season, season_type, (sum(pts) / "nullif"(sum(gp), 0)) AS league_points_per_game FROM nba_fixture.marts.team_season GROUP BY season, season_type), m1 AS (SELECT season, season_type, (sum(fg3a) / "nullif"(sum(fga), 0)) AS league_three_point_attempt_rate FROM nba_fixture.marts.team_season GROUP BY season, season_type)SELECT spine.*, m0.league_points_per_game, m1.league_three_point_attempt_rate FROM spine LEFT JOIN m0 ON (((m0.season = spine.season) AND (m0.season_type = spine.season_type))) LEFT JOIN m1 ON (((m1.season = spine.season) AND (m1.season_type = spine.season_type)));;
