CREATE VIEW semantic.player_titles AS SELECT pt.*, p."name" AS player_name FROM nba_fixture.marts.player_titles AS pt INNER JOIN nba_fixture.marts.players AS p USING (player_id);;
CREATE VIEW semantic.records AS SELECT r.*, p."name" AS player_name FROM nba_fixture.marts.records AS r LEFT JOIN nba_fixture.marts.players AS p USING (player_id);;
CREATE VIEW semantic.registry_info AS SELECT '0.3.0' AS registry_version, 54 AS metric_count;;
CREATE VIEW semantic.shots AS SELECT s.*, p."name" AS player_name FROM nba_fixture.marts.shots AS s INNER JOIN nba_fixture.marts.players AS p USING (player_id);;
CREATE VIEW semantic.stat_availability AS SELECT * FROM nba_fixture.seeds.stat_availability;;
CREATE VIEW semantic.teams AS SELECT * FROM nba_fixture.marts.teams;;
CREATE VIEW semantic.team_aliases AS SELECT * FROM nba_fixture.marts.team_aliases;;
CREATE VIEW semantic.team_all_time_stats AS WITH spine AS (SELECT f.franchise_id, f.current_name AS team_name, st.season_type FROM nba_fixture.marts.franchises AS f , (SELECT DISTINCT season_type FROM nba_fixture.marts.team_season) AS st), m0 AS (SELECT franchise_id, season_type, sum(wins) AS wins FROM nba_fixture.marts.team_season GROUP BY franchise_id, season_type), m1 AS (SELECT franchise_id, season_type, sum(losses) AS losses FROM nba_fixture.marts.team_season GROUP BY franchise_id, season_type), m2 AS (SELECT franchise_id, season_type, (sum(wins) / "nullif"(sum(gp), 0)) AS win_pct FROM nba_fixture.marts.team_season GROUP BY franchise_id, season_type), m3 AS (SELECT franchise_id, season_type, (sum(pts) / "nullif"(sum(gp), 0)) AS team_points_per_game FROM nba_fixture.marts.team_season GROUP BY franchise_id, season_type), m4 AS (SELECT franchise_id, season_type, (sum(opp_pts) / "nullif"(sum(gp), 0)) AS opponent_points_per_game FROM nba_fixture.marts.team_season GROUP BY franchise_id, season_type), m5 AS (SELECT franchise_id, count_star() AS championships FROM nba_fixture.marts.team_titles GROUP BY franchise_id)SELECT spine.*, m0.wins, m1.losses, m2.win_pct, m3.team_points_per_game, m4.opponent_points_per_game, m5.championships FROM spine LEFT JOIN m0 ON (((m0.franchise_id = spine.franchise_id) AND (m0.season_type = spine.season_type))) LEFT JOIN m1 ON (((m1.franchise_id = spine.franchise_id) AND (m1.season_type = spine.season_type))) LEFT JOIN m2 ON (((m2.franchise_id = spine.franchise_id) AND (m2.season_type = spine.season_type))) LEFT JOIN m3 ON (((m3.franchise_id = spine.franchise_id) AND (m3.season_type = spine.season_type))) LEFT JOIN m4 ON (((m4.franchise_id = spine.franchise_id) AND (m4.season_type = spine.season_type))) LEFT JOIN m5 ON ((m5.franchise_id = spine.franchise_id));;
CREATE VIEW semantic.team_season_stats AS WITH spine AS (SELECT ts.team_id, t.full_name AS team_name, ts.season, ts.season_start, ts.season_type, ts.conference, ts.division, ts.conference_rank, ts.league_rank, ts.gp, ts.neutral_games, ts.road_wins, ts.road_losses FROM nba_fixture.marts.team_season AS ts LEFT JOIN nba_fixture.marts.teams AS t ON (((t.team_id = ts.team_id) AND (ts.season_start BETWEEN t.first_season_start AND t.last_season_start)))), m0 AS (SELECT team_id, season, season_type, sum(wins) AS wins FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m1 AS (SELECT team_id, season, season_type, sum(losses) AS losses FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m2 AS (SELECT team_id, season, season_type, (sum(wins) / "nullif"(sum(gp), 0)) AS win_pct FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m3 AS (SELECT team_id, season, season_type, (sum(pts) / "nullif"(sum(gp), 0)) AS team_points_per_game FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m4 AS (SELECT team_id, season, season_type, (sum(opp_pts) / "nullif"(sum(gp), 0)) AS opponent_points_per_game FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m5 AS (SELECT team_id, season, season_type, max(off_rating) AS offensive_rating FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m6 AS (SELECT team_id, season, season_type, max(def_rating) AS defensive_rating FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m7 AS (SELECT team_id, season, season_type, max(net_rating) AS net_rating FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m8 AS (SELECT team_id, season, season_type, max(pace) AS pace FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m9 AS (SELECT team_id, season, season_type, sum(home_wins) AS home_wins FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m10 AS (SELECT team_id, season, season_type, sum(home_losses) AS home_losses FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m11 AS (SELECT team_id, season, season_type, sum(road_wins) AS road_wins FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type), m12 AS (SELECT team_id, season, season_type, sum(road_losses) AS road_losses FROM nba_fixture.marts.team_season GROUP BY team_id, season, season_type)SELECT spine.*, m0.wins, m1.losses, m2.win_pct, m3.team_points_per_game, m4.opponent_points_per_game, m5.offensive_rating, m6.defensive_rating, m7.net_rating, m8.pace, m9.home_wins, m10.home_losses, m11.road_wins, m12.road_losses FROM spine LEFT JOIN m0 ON (((m0.team_id = spine.team_id) AND (m0.season = spine.season) AND (m0.season_type = spine.season_type))) LEFT JOIN m1 ON (((m1.team_id = spine.team_id) AND (m1.season = spine.season) AND (m1.season_type = spine.season_type))) LEFT JOIN m2 ON (((m2.team_id = spine.team_id) AND (m2.season = spine.season) AND (m2.season_type = spine.season_type))) LEFT JOIN m3 ON (((m3.team_id = spine.team_id) AND (m3.season = spine.season) AND (m3.season_type = spine.season_type))) LEFT JOIN m4 ON (((m4.team_id = spine.team_id) AND (m4.season = spine.season) AND (m4.season_type = spine.season_type))) LEFT JOIN m5 ON (((m5.team_id = spine.team_id) AND (m5.season = spine.season) AND (m5.season_type = spine.season_type))) LEFT JOIN m6 ON (((m6.team_id = spine.team_id) AND (m6.season = spine.season) AND (m6.season_type = spine.season_type))) LEFT JOIN m7 ON (((m7.team_id = spine.team_id) AND (m7.season = spine.season) AND (m7.season_type = spine.season_type))) LEFT JOIN m8 ON (((m8.team_id = spine.team_id) AND (m8.season = spine.season) AND (m8.season_type = spine.season_type))) LEFT JOIN m9 ON (((m9.team_id = spine.team_id) AND (m9.season = spine.season) AND (m9.season_type = spine.season_type))) LEFT JOIN m10 ON (((m10.team_id = spine.team_id) AND (m10.season = spine.season) AND (m10.season_type = spine.season_type))) LEFT JOIN m11 ON (((m11.team_id = spine.team_id) AND (m11.season = spine.season) AND (m11.season_type = spine.season_type))) LEFT JOIN m12 ON (((m12.team_id = spine.team_id) AND (m12.season = spine.season) AND (m12.season_type = spine.season_type)));;
CREATE VIEW semantic.team_titles AS SELECT * FROM nba_fixture.marts.team_titles;;

